//autogenerated:yes
//nolint:revive,govet,errcheck
package common_test

import (
	"testing"

	"github.com/stretchr/testify/require"

	dialectpkg "github.com/bluenviron/gomavlib/v4/pkg/dialects/common"
)

func TestEnum_SERIAL_CONTROL_DEV(t *testing.T) {
	t.Run("zero", func(t *testing.T) {
		var e dialectpkg.SERIAL_CONTROL_DEV
		e.UnmarshalText([]byte{})
		e.MarshalText()
		e.String()
	})

	t.Run("first entry", func(t *testing.T) {
		enc, err := dialectpkg.SERIAL_CONTROL_DEV_TELEM1.MarshalText()
		require.NoError(t, err)

		var dec dialectpkg.SERIAL_CONTROL_DEV
		err = dec.UnmarshalText(enc)
		require.NoError(t, err)

		require.Equal(t, dialectpkg.SERIAL_CONTROL_DEV_TELEM1, dec)
	})
}
